package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods on each sheet. */
@Repository
public class PeriodStore {

    private final RowMapper<PeriodResponse> ROW = (rs, i) -> PeriodResponse.of(rs.getString("name"),
            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
            rs.getBoolean("closed") || rs.getBoolean("soft") ? personTotals(rs.getString("sheet_id"), rs.getString("name"))
                    : Map.of(),
            rs.getBoolean("soft"), cap(rs));

    private final JdbcTemplate jdbc;

    public PeriodStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<PeriodResponse> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** Every period on the sheet as the periods and their fixed figures stood at the end of the date (see
     *  {@link History}), by from-date. */
    public List<PeriodResponse> listAsOf(String sheetId, LocalDate date) {
        String totals = History.asOf("period_person_total", "sheet_id, period_name, person_id", date);
        return jdbc.query("SELECT * FROM " + History.asOf("period", "id", date) + " WHERE sheet_id = ? ORDER BY from_date",
                (rs, i) -> PeriodResponse.of(rs.getString("name"), rs.getObject("from_date", LocalDate.class),
                        rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"),
                        rs.getBigDecimal("closed_total"),
                        rs.getBoolean("closed") || rs.getBoolean("soft")
                                ? personTotals(rs.getString("sheet_id"), rs.getString("name"), totals)
                                : Map.of(),
                        rs.getBoolean("soft"), cap(rs)),
                sheetId);
    }

    /** The period on the sheet with this name, or null when there is none. */
    public PeriodResponse find(String sheetId, String name) {
        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ?", ROW, sheetId,
                name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The closed period on the sheet whose dates contain the date, or null when none does. */
    public PeriodResponse closedOn(String sheetId, LocalDate date) {
        List<PeriodResponse> found = jdbc.query(
                "SELECT * FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?", ROW, sheetId,
                date, date);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the period on the sheet whose dates contain the date is soft-closed. */
    public boolean softOn(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, date, date);
        return n != null && n > 0;
    }

    /** The period on the sheet whose dates contain the date, or null when none does. */
    public PeriodResponse on(String sheetId, LocalDate date) {
        List<PeriodResponse> found = jdbc.query(
                "SELECT * FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", ROW, sheetId, date, date);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether a period on the sheet has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
                Integer.class, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether a period on the sheet shares a day with from..to (inclusive). */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", Integer.class,
                sheetId, to, from);
        return n != null && n > 0;
    }

    public void add(String sheetId, PeriodInput period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, open_cap) VALUES (?, ?, ?, ?, ?)", sheetId,
                period.name(), period.from(), period.to(), period.cap());
    }

    private static Integer cap(java.sql.ResultSet rs) throws java.sql.SQLException {
        int cap = rs.getInt("open_cap");
        return rs.wasNull() ? null : cap;
    }

    /** Each person's due-total fixed when the period was closed, by person id. */
    private Map<Long, BigDecimal> personTotals(String sheetId, String name) {
        return personTotals(sheetId, name, "period_person_total");
    }

    private Map<Long, BigDecimal> personTotals(String sheetId, String name, String table) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM " + table + " WHERE sheet_id = ? AND period_name = ? ORDER BY person_id",
                rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, sheetId, name);
        return totals;
    }

    /** Fixes each person's due-total in the period as it is when it is closed. */
    public void fixPersonTotals(String sheetId, String name, Map<Long, BigDecimal> totals) {
        totals.forEach((personId, total) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                sheetId, name, personId, total));
    }

    /** Drops each person's due-total fixed in the period (as a soft close fixed them, before they are fixed afresh). */
    public void dropPersonTotals(String sheetId, String name) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", sheetId, name);
    }

    /** Closes the open (or soft-closed) period with its due-total fixed; false when it is already closed
     *  (another user closed it first). */
    public boolean close(String sheetId, String name, BigDecimal total) {
        return jdbc.update("UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? "
                + "WHERE sheet_id = ? AND name = ? AND NOT closed", total, sheetId, name) == 1;
    }

    /** Soft-closes the open period with its due-total fixed; false when it is already closed or soft-closed. */
    public boolean softClose(String sheetId, String name, BigDecimal total) {
        return jdbc.update("UPDATE period SET soft = TRUE, closed_total = ? "
                + "WHERE sheet_id = ? AND name = ? AND NOT closed AND NOT soft", total, sheetId, name) == 1;
    }

    /** Reopens the closed or soft-closed period, dropping its fixed due-total; false when it is neither
     *  (another user reopened it first). */
    public boolean reopen(String sheetId, String name) {
        dropPersonTotals(sheetId, name);
        return jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL "
                + "WHERE sheet_id = ? AND name = ? AND (closed OR soft)", sheetId, name) == 1;
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's periods as they are now, or as they stood at the end of the {@code asOf} date. */
public class RespondWithPeriods {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, PeriodStore store,
            ObjectResponse<List<PeriodResponse>> response) {
        LocalDate on = History.date(asOf);
        response.send(on == null ? store.list(sheetId.trim()) : store.listAsOf(sheetId.trim(), on));
    }
}
import { Fragment } from 'react';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { useClaims } from '../claims/claims';
import { useRates } from '../rates/rates';
import { floorOf, useSettings } from '../settings/settings';
import { lateOf } from '../overdue/overdue';
import { personPeriodCarried, personPeriodDue, usePeriods } from './periods';
import { useFigure } from '../locale/locale';

// For every period on the sheet, a person's due-total for it: live while the period is open, fixed
// when it was closed; and the figure carried into it from earlier periods' claims still open at its end.
function PeriodHeads() {
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <Fragment key={p.name}>
          <th>{p.name} due</th>
          <th>{p.name} carried</th>
        </Fragment>
      ))}
    </>
  );
}

function PersonPeriods({ person }: { person: Person }) {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const late = lateOf(settings, today, [person]);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <Fragment key={p.name}>
          <td data-testid={`person-period-${p.name}-due-total`}>
            {fig(personPeriodDue(p, person, claims.data, rates.data, floorOf(settings), late))}
          </td>
          <td data-testid={`person-period-${p.name}-carried`}>
            {fig(personPeriodCarried(p, periods.data, person, claims.data, rates.data, floorOf(settings), late))}
          </td>
        </Fragment>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 16, Component: PeriodHeads }),
  PersonColumns.fill({ order: 16, Component: PersonPeriods }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';
import { type Claim, type ClaimStatus, isOpen } from '../claims/claims';
import { covers } from '../people/people';
import type { Person } from '../people/people';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';

/** A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, once closed, the due-total fixed on closing (null while open) and each person's
 *  due-total fixed on closing, by person id (empty while open), and whether it is soft-closed: not closed,
 *  but with those figures fixed as when it was soft-closed, and the most OPEN or PENDING claims a person may
 *  have in it (null for no cap). No two periods on a sheet overlap. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  total: string | null;
  people: Record<string, string>;
  soft: boolean;
  cap: number | null;
};

/** Whether the period's figures are fixed: it is closed or soft-closed. */
export const isFixed = (period: Period) => period.closed || period.soft;

/** Under the sheet's key, so loading the sheet again re-reads its periods. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;

/** Every period on the sheet, by from-date. */
export function usePeriods(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(periodsKey(sheet), asOf),
    queryFn: () => getJson<Period[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
    enabled: sheet !== '',
  });
}

/** Whether the date (yyyy-MM-dd) falls in the period. */
export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;

/** The period whose dates contain the date, or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => contains(p, date));
}

/** The claim's status at the end of the day (yyyy-MM-dd), as its status log records it (each line
 *  dated the sheet's today when the change was made); null when it had not been added by then. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of claim.log ?? []) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= date) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether the claim counts toward a period: by the status it had at the end of the period's last
 *  day it was OPEN, PENDING or SETTLED; and, as the live rules say, it is not deferred on the sheet's
 *  today, nor (while open then and still open now, and unbound by a statement) dated within one of its person's holds
 *  or of a person whose retirement date the sheet's today has reached. */
export function countsInPeriod(claim: Claim, period: Period, person: Person): boolean {
  const status = statusAt(claim, period.to);
  if (status === 'SETTLED') return true;
  if (status !== 'OPEN' && status !== 'PENDING') return false;
  return !(claim.status !== 'VOID' && claim.deferred) && (claim.stated || !isOpen(claim) || !(person.retiredNow || person.holds.some((h) => covers(h, claim.date))));
}

/** A person's due-total for a period: once closed or soft-closed, the figure fixed then (0.00 for a person
 *  added since); else the sum of the figures (as shown now) of their claims whose due-by falls in it
 *  and that count by their status at the period's end, skipping n/a. */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  if (isFixed(period)) return period.people?.[String(person.id)] ?? '0.00';
  return dueTotal(
    (claims ?? [])
      .filter((c) => c.personId === person.id && contains(period, c.dueBy) && countsInPeriod(c, period, person))
      .map((c) => claimDue(c, rates, person.grades, floor, late)),
  );
}

/** A person's carried figure for a period: the sum of the figures (as shown now) of their claims that count
 *  in it, whose due-by falls in a period ending before it starts, and that were still OPEN or PENDING at
 *  its end by their status log, skipping n/a; 0.00 when nothing is carried. */
export function personPeriodCarried(
  period: Period,
  periods: Period[] | undefined,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  const earlier = (periods ?? []).filter((p) => p.to < period.from);
  return dueTotal(
    (claims ?? [])
      .filter((c) => c.personId === person.id && earlier.some((p) => contains(p, c.dueBy)))
      .filter((c) => {
        const status = statusAt(c, period.to);
        return (status === 'OPEN' || status === 'PENDING') && countsInPeriod(c, period, person);
      })
      .map((c) => claimDue(c, rates, person.grades, floor, late)),
  );
}

/** A period's due-total as the list shows it: the sum of the people's due-totals for it. */
export function periodDue(
  period: Period,
  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
}
