  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <Fragment key={p.name}>
          <th>{p.name} due</th>
          <th>{p.name} carried</th>
        </Fragment>
      ))}
    </>
  );
}

