import { createContext, useContext } from 'react';
import { asString, useSearchParam } from '../url/useSearchParam';

// The signed-in name and the active sheet id live in the URL (`user`, `sheet`), so every feature
// reads them directly and each browser tab is its own session.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// The date this screen shows the sheet as of (`asOf`, yyyy-MM-dd; '' for as it is now). It belongs to
// the screen, not the sheet: other users' screens are unaffected, and every change is refused while it is set.
export function useAsOf(): [string, (value: string | undefined) => void] {
  const [asOf, setAsOf] = useSearchParam('asOf', asString);
  return [useContext(LiveView) ? '' : asOf, setAsOf];
}

/** Within it, every read shows the sheet as it is now, whatever the screen's as-of date. */
export const LiveView = createContext(false);

/** The screen's as-of date read outside React (by the fetch surface), '' when none is set. */
export const currentAsOf = (): string => new URLSearchParams(window.location.search).get('asOf') ?? '';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useAsOf } from '../../session/session';

/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default uses it, never the clock.
 *  An `archived` sheet stays visible but the server refuses every change to it. `asOf` (yyyy-MM-dd) is the
 *  date this screen shows the sheet as of, null when it shows it as it is now; `archived` is then as it
 *  stood at the end of that date. */
export type Sheet = { id: string; today: string; archived: boolean; asOf: string | null };

/** Every per-sheet query key starts with ['sheet', id], so loading a sheet re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

/** A per-sheet query key as read for the screen's as-of date: the key itself when there is none, so a
 *  change made (never while one is set) updates the very queries it read. */
export const asOfKey = <K extends readonly unknown[]>(key: K, asOf: string) =>
  (asOf === '' ? key : [...key, { asOf }]) as unknown as K;

/** A read path with the screen's as-of date added (as `asOf`), so the server answers as it stood then. */
export const asOfPath = (path: string, asOf: string) =>
  asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;

export function useSheet(id: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(sheetKey(id), asOf),
    queryFn: () => getJson<Sheet>(asOfPath(`/api/sheets/${encodeURIComponent(id)}`, asOf)),
    enabled: id !== '',
  });
}

/** The sheet's today (yyyy-MM-dd), or undefined while the sheet loads. Use it for every default date.
 *  While the screen shows the sheet as of a date, that date stands in for it in every figure. */
export function useSheetToday(id: string): string | undefined {
  const data = useSheet(id).data;
  return data?.asOf ?? data?.today;
}
package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.stream.Collectors;

/** Reads a table as it stood at the end of a date, from the versions {@link HistoryTrigger} keeps: each row's
 *  last version made while the sheet's today was on or before the date, unless that version deleted it. A
 *  change made while the sheet's today was after the date does not count, whenever it was made. */
public final class History {
    private History() {
    }

    /** The date of an {@code asOf} query parameter (yyyy-MM-dd): null when absent or blank, so the store is
     *  read as it is now. */
    public static LocalDate date(String asOf) {
        return asOf == null || asOf.isBlank() ? null : LocalDate.parse(asOf.trim());
    }

    /** A table expression, named as the table, for use in place of it in a query's FROM: the table's rows
     *  (each identified by {@code keys}, comma separated) as they stood at the end of {@code date}. */
    public static String asOf(String table, String keys, LocalDate date) {
        String on = "DATE '" + date + "'";
        String same = Arrays.stream(keys.split(",")).map(String::trim).map(k -> "l." + k + " = h." + k)
                .collect(Collectors.joining(" AND "));
        return "(SELECT h.* FROM " + table + "_hist h WHERE h.hist_made_on <= " + on + " AND NOT EXISTS (SELECT 1 FROM "
                + table + "_hist l WHERE " + same + " AND l.hist_made_on <= " + on + " AND l.hist_seq > h.hist_seq) AND NOT h.hist_gone) "
                + table;
    }
}
