package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Closes the period, fixing its due-total and each person's due-total in it as they are now: the figures of the claims whose due-by falls in
 *  it and that count by their status at its end, skipping n/a. Refused when the sheet's permission matrix does not allow the user's role to close (by default a clerk or a steward),
 *  there is no such period or it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            @Val CloseRequest request, PeriodStore store, RoleStore roles, SettingStore settings, RollupService rollups,
            Out<PeriodResponse> closed) throws InvalidSheetException {
        String sheet = sheetId.trim();
        Role role = roles.find(sheet, request.user());
        if (!settings.allows(sheet, "close", role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not close a period");
        }
        PeriodResponse period = store.find(sheet, periodName.trim());
        if (period == null) {
            throw new InvalidSheetException("No such period: " + periodName.trim());
        }
        if (period.closed()) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        closed.set(PeriodClosing.fix(sheet, period, store, rollups));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Soft-closes the period, fixing its due-total and each person's due-total in it as they are now, as a close
 *  does, while claims due by a date inside it may still be added, edited and moved on. Refused as a close is: when the
 *  sheet's permission matrix does not allow the user's role to close, there is no such period, or it is
 *  already closed or soft-closed. */
public class SoftClosePeriod {
    public void softClose(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            @Val CloseRequest request, PeriodStore store, RoleStore roles, SettingStore settings, RollupService rollups,
            Out<PeriodResponse> closed) throws InvalidSheetException {
        String sheet = sheetId.trim();
        Role role = roles.find(sheet, request.user());
        if (!settings.allows(sheet, "close", role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not close a period");
        }
        PeriodResponse period = store.find(sheet, periodName.trim());
        if (period == null) {
            throw new InvalidSheetException("No such period: " + periodName.trim());
        }
        if (period.closed() || period.soft()) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        closed.set(PeriodClosing.fixSoft(sheet, period, store, rollups));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** How a period is closed, by hand or by a new today past its grace days. */
public final class PeriodClosing {

    private PeriodClosing() {
    }

    /** Closes the open (or soft-closed) period, fixing its due-total and each person's due-total in it as
     *  they are now; refused when it was closed meanwhile. Shared by a close by hand and the auto close of a new today. */
    public static PeriodResponse fix(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups)
            throws InvalidSheetException {
        return fix(sheet, period, store, rollups, false);
    }

    /** Soft-closes the open period, fixing its figures as {@link #fix} does while leaving its claims open
     *  to change; refused when it was closed or soft-closed meanwhile. */
    public static PeriodResponse fixSoft(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups)
            throws InvalidSheetException {
        return fix(sheet, period, store, rollups, true);
    }

    private static PeriodResponse fix(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups,
            boolean soft) throws InvalidSheetException {
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        Map<Long, BigDecimal> people = rollups.dueBetweenByPerson(sheet, from, to);
        BigDecimal total = people.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (!(soft ? store.softClose(sheet, period.name(), total) : store.close(sheet, period.name(), total))) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        store.dropPersonTotals(sheet, period.name());
        store.fixPersonTotals(sheet, period.name(), people);
        return PeriodResponse.of(period.name(), from, to, !soft, total, people, soft, period.cap());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;

/** A period as the front end reads it: its name, its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, when closed, the due-total fixed on closing (two decimals; null while open) and each
 *  person's due-total fixed on closing, by person id (empty while open; a person missing shows 0.00), and
 *  whether it is soft-closed: not closed, but with its figures fixed (total and people) as when it was soft-closed,
 *  and the most OPEN or PENDING claims a person may have in it (null for no cap). */
public record PeriodResponse(String name, String from, String to, boolean closed, String total,
        Map<Long, String> people, boolean soft, Integer cap) {
    public static PeriodResponse of(String name, LocalDate from, LocalDate to, Integer cap) {
        return of(name, from, to, false, null, Map.of(), false, cap);
    }

    public static PeriodResponse of(String name, LocalDate from, LocalDate to, boolean closed, BigDecimal total,
            Map<Long, BigDecimal> people, boolean soft, Integer cap) {
        Map<Long, String> shown = new LinkedHashMap<>();
        people.forEach((id, t) -> shown.put(id, t.setScale(2).toPlainString()));
        return new PeriodResponse(name, from.toString(), to.toString(), closed,
                total == null ? null : total.setScale(2).toPlainString(), shown, soft, cap);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

